function fresh(){return {version:3,cash:0,followers:0,clicks:0,levels:{},upgrades:0,seconds:0,idle:0,finished:false,feed:[],milestones:[],nextGoal:100,lastGoal:null,kept:[],peakSeconds:0,errorSeen:false,escaped:false,returns:0,practice:0,infill:[],achievements:[],goal:{id:defaultGoal(),level:15,reached:false}};}
function load(){try{const s=JSON.parse(sessionStorage.getItem(KEY));if(!s||s.version!==3||!['cash','followers','clicks','seconds','upgrades','nextGoal'].every(k=>Number.isFinite(s[k])&&s[k]>=0&&s[k]<=MAX)||!s.levels||!products.every(p=>Number.isInteger(s.levels[p.id]||0)&&(s.levels[p.id]||0)>=0&&(s.levels[p.id]||0)<180)||!Array.isArray(s.feed)||!Array.isArray(s.milestones))return fresh();return {...fresh(),...s,idle:0};}catch{return fresh();}}
