function persist(){try{state.kept=[...selected];state.missionTitle=$('#mission-title').textContent;state.missionCopy=$('#mission-copy').textContent;sessionStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function level(p){return state.levels[p.id]||0;}
function currentName(p){const l=level(p);return l?p.tiers[Math.min(l-1,p.tiers.length-1)]+(l>p.tiers.length?' / STUFE '+l:''):p.base;}
function nextName(p){const l=level(p);return p.tiers[Math.min(l,p.tiers.length-1)]+(l>=p.tiers.length?' / STUFE '+(l+1):'');}
function price(p){return Math.min(MAX,Math.ceil(p.cost*2.2**level(p)));}
function bonus(p,key){return Math.floor(p[key]*(key==='cash'?1.34:1.62)**level(p));}
function restBonus(){return Math.min(.15,(state.rest||0)/60*.01);}
function routineBonus(){return 1+Math.min(.18,Math.floor((state.practice||0)/20)*.03)+restBonus();}
function pauseSeconds(){return state.pauseAt?Math.min(300,Math.max(0,(Date.now()-state.pauseAt)/1000)):0;}
function reliefNow(){if(!state.relief)return 0;return state.relief*Math.max(0,1-(state.seconds-(state.reliefT||0))/150);}
function applyReturn(){const s=pauseSeconds();state.pauseAt=0;state.lastPause=Math.round(s);if(s<25){state.returns=(state.returns||0)+1;state.floor=.85+Math.min(.14,state.returns*.03);state.relief=0;return 'rush';}const r=Math.min(1,s/90);state.rest=(state.rest||0)+s;state.returns=0;state.floor=Math.max(0,.4*(1-r));state.relief=r;state.reliefT=state.seconds;if(state.goal&&!state.goal.reached)state.goal.level=Math.max(5,15-Math.floor(state.rest/30));return 'rested';}
function rates(){let cash=20,fans=5;for(const p of products)for(let i=0;i<level(p);i++){cash+=p.cash*1.34**i;fans+=p.fans*1.62**i;}const vf=typeof vitalFactor==='function'?vitalFactor():1;return {cash:Math.min(MAX,Math.floor(cash*routineBonus()*vf)),fans:Math.min(MAX,Math.floor(fans*routineBonus()*vf))};}
function unlocked(){return Math.min(12,4+Math.floor(state.upgrades/3)*2);}
function earlyPhase(){return state.upgrades<6&&state.seconds<120&&!state.returns;}
function pressure(){const floor=state.idle<8&&state.clicks?Math.max(0,(state.seconds-200)/420):0;const objective=Math.min(1,Math.max(floor,.045+state.upgrades*.024+Math.max(0,Math.log10(Math.max(1,state.followers))-2)*.045));const eff=Math.max(state.seconds,Math.min(400,Math.max(0,Math.log10(Math.max(1,state.followers))-3)*70));const pace=.16+.84*Math.pow(Math.min(1,eff/400),1.5);const base=Math.max(Math.min(objective,pace),state.floor||0,typeof vitalStress==='function'?vitalStress():0);return Math.min(1,base*(1-reliefNow()*.85));}
function darkness(){return Math.min(1,Math.max(0,state.idle-4)/32);}
function formatTime(n){n=Math.floor(n);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
