function tile(x,y,c){poly([[x,y-10],[x+22,y],[x,y+10],[x-22,y]],c);}
function block(x,y,w,d,h,left='#46513a',right='#303b2a',roof='#65704c',windows=true){poly([[x-w,y-d/2-h],[x,y-h],[x,y],[x-w,y-d/2]],left);poly([[x,y-h],[x+w,y-d/2-h],[x+w,y-d/2],[x,y]],right);poly([[x,y-d-h],[x+w,y-d/2-h],[x,y-h],[x-w,y-d/2-h]],roof);if(windows){for(let j=5;j<h-3;j+=7){for(let i=4;i<w-2;i+=6){const lit=((i+j+Math.floor(x))%5)!==0;rect(x-w+i,y-h-d/2+j,2,3,lit?'#b0bb66':'#263123');rect(x+i-1,y-h+j-2,2,3,lit?'#889a52':'#242d22');}}}}
