function home(x,y,l){if(l<2){block(x,y,12,13,24+l*5,'#61634c','#3c4936','#7b7e53');rect(x-2,y-4,4,5,'#252e25');if(l)rect(x-9,y-29,12,2,'#c9d35e');}else if(l===2){for(let n=-1;n<=1;n++){block(x+n*11,y+Math.abs(n)*3,7,9,17,'#7a7154','#514f38','#9c7f55');poly([[x+n*11-8,y+Math.abs(n)*3-21],[x+n*11,y+Math.abs(n)*3-29],[x+n*11+8,y+Math.abs(n)*3-21],[x+n*11,y+Math.abs(n)*3-18]],'#81513e');}}else{const w=14+Math.min(l,7);block(x,y,w,15,19+Math.min(l,5),'#8b8861','#606a48','#a5a975');poly([[x-w-2,y-31],[x,y-43],[x+w+2,y-31],[x,y-23]],l>=4?'#6c7380':'#875746');rect(x-2,y-8,5,9,'#374134');if(l>=4){poly([[x+21,y+2],[x+39,y-5],[x+51,y+1],[x+32,y+9]],'#477678');poly([[x+24,y+1],[x+39,y-3],[x+47,y+1],[x+33,y+6]],'#7faaa0');block(x-20,y+5,8,10,12,'#777852','#47583f','#8e9a65');}if(l>=5){tree(x-38,y+6);tree(x+48,y-8);}}}
