 for(let total=0;total<=2*(size-1);total++)for(let a=0;a<size;a++){const b=total-a;if(b<0||b>=size)continue;const q=iso(a,b),screen=projectMap(q);if(screen.x<-35||screen.x>w+35||screen.y<-70||screen.y>h+35)continue;const road=a===3||b===4||a%8===3||b%8===4;const born=constructions.get('ring'+Math.max(a,b));ctx.globalAlpha=born!==undefined&&!motionReduced?Math.min(1,(time-born)/1200):1;tile(q.x,q.y,road?'#293630':(a+b)%2?'#394833':'#34452f');if(road){rect(q.x-2,q.y,4,1,'#6c7455');}else{for(let k=0;k<5;k++)rect(q.x-13+(a*7+b*11+k*13)%26,q.y-4+(a*3+b*7+k*3)%8,1,1,'#4e5f3e');}}
 ctx.globalAlpha=1;
 for(const [a,b] of [[0,0],[0,size-1],[size-1,size-1],[size-1,3],[4,0],[2,6],[4,1]]){const q=iso(a,b);tree(q.x,q.y,a%2);}
