new ResizeObserver(resizeWorld).observe($('#scene'));
function frame(t){const dt=document.hidden?0:Math.min(.1,(t-lastAnimationTick)/1000);lastAnimationTick=t;if(!document.hidden){animationTime+=dt*1000;window.FX?.frame(dt);if(!state.finished&&!failureOpen){drawWorld(motionReduced?0:animationTime);window.FX?.post(dt);}if(!$('#retreat').hidden)advanceCountry(dt); }requestAnimationFrame(frame);}
