// Chiptune sequencer. Short-lived voices are stopped; there is one persistent bus.
let audio,master,compressor,drone,droneGain,noiseBuffer,soundRunning=false,nextNote=0,step=0,musicInterval=null,fxBus,ambientBus;
function tempo(){return Math.min(320,Math.round(92+pressure()*166+(state.returns||0)*32));}
function setupAudio(){const Context=window.AudioContext||window.webkitAudioContext;if(!Context){notify('DIESER BROWSER UNTERSTÜTZT KEIN AUDIO.');return false;}audio=new Context();master=audio.createGain();master.gain.value=0;compressor=audio.createDynamicsCompressor();compressor.threshold.value=-20;compressor.knee.value=15;compressor.ratio.value=12;compressor.attack.value=.003;compressor.release.value=.12;master.connect(compressor).connect(audio.destination);fxBus=audio.createGain();fxBus.gain.value=volume*.14;fxBus.connect(compressor);ambientBus=audio.createGain();ambientBus.gain.value=0;ambientBus.connect(compressor);drone=audio.createOscillator();drone.type='sawtooth';drone.frequency.value=36.71;droneGain=audio.createGain();droneGain.gain.value=0;drone.connect(droneGain).connect(master);drone.start();noiseBuffer=audio.createBuffer(1,audio.sampleRate*.12,audio.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;nextNote=audio.currentTime+.05;musicInterval=setInterval(scheduleMusic,25);return true;}
async function activateSound(){if(!soundWanted)return;try{if(!audio&&!setupAudio())return;if(soundRunning&&audio.state==='running')return;await audio.resume();soundRunning=true;nextNote=audio.currentTime+.03;ambientNext=audio.currentTime+.1;renderSound();updateAudio();}catch{notify('SOUND OBEN RECHTS AKTIVIEREN.');}}
function voice(freq,t,length,gain=.1,type='square'){if(!audio)return;const osc=audio.createOscillator(),g=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(gain,t+.003);g.gain.exponentialRampToValueAtTime(.0001,t+length);osc.connect(g).connect(master);osc.start(t);osc.stop(t+length+.015);}
