function scheduleMusic(){if(!audio)return;if(state.finished){scheduleCountryAudio();return;}if(!soundWanted||!soundRunning||state.finished||failureOpen||goalModalOpen()||document.hidden||audio.state!=='running'){nextNote=audio.currentTime+.05;return;}if(nextNote<audio.currentTime)nextNote=audio.currentTime+.02;const p=pressure(),notes=p>.65?[0,1,7,6,12,13,7,11,0,6,1,7,13,12,6,11]:[0,7,12,7,3,7,10,7,0,7,12,15,10,7,3,7];let guard=0;while(nextNote<audio.currentTime+.1&&guard++<8){const n=step%16,t=nextNote;const root=130.81;voice(root*2**(notes[n]/12)*(p>.75?2:1),t,.055+p*.025,.055+p*.045,'square');if(n%4===0){voice(n%8===0?65.4:73.4,t,.13,.14,'triangle');const kick=audio.createOscillator(),g=audio.createGain();kick.frequency.setValueAtTime(115,t);kick.frequency.exponentialRampToValueAtTime(38,t+.06);g.gain.setValueAtTime(.18,t);g.gain.exponentialRampToValueAtTime(.0001,t+.08);kick.connect(g).connect(master);kick.start(t);kick.stop(t+.1);}if(p>.28&&n%2===0)hat(t,.015+p*.035);if(p>.62&&n%2===1)hat(t,.02);if(p>.8&&n%4===2)voice(root*2**((notes[n]+1)/12),t,.07,.06,'sawtooth');window.FX?.music(t,n,p);nextNote+=60/tempo()/4;step++;}}
function updateAudio(){if(!master)return;const live=soundWanted&&soundRunning&&!document.hidden;const p=pressure(),d=darkness();master.gain.setTargetAtTime(live&&!state.finished&&!failureOpen&&!goalModalOpen()?volume*(.09+p*.55)*(window.FX?window.FX.duck:1):0,audio.currentTime,state.finished?1.1:failureOpen?.04:.25);droneGain.gain.setTargetAtTime(live&&!state.finished&&!failureOpen?d*.12:0,audio.currentTime,.4);fxBus.gain.setTargetAtTime(live&&!state.finished&&!failureOpen&&!goalModalOpen()?volume*.14:0,audio.currentTime,.04);ambientBus.gain.setTargetAtTime(live&&state.finished?volume*.35:0,audio.currentTime,1.5);}
function clickTap(){if(!audio||!soundWanted||!soundRunning||state.finished||failureOpen)return;const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),g=audio.createGain();source.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.value=460;const t=audio.currentTime;g.gain.setValueAtTime(.055,t);g.gain.exponentialRampToValueAtTime(.0001,t+.018);source.connect(filter).connect(g).connect(fxBus);source.start(t);source.stop(t+.022);}
function blip(freq,duration,gain){if(!audio||!soundWanted||!soundRunning||document.hidden||state.finished||failureOpen)return;voice(Math.min(1600,freq),audio.currentTime+.01,duration,gain,'square');}
function renderSound(){$('#retreat-sound').textContent=soundWanted?(soundRunning?'SOUND AN':'SOUND STARTEN'):'SOUND AUS';$('#retreat-sound').setAttribute('aria-pressed',String(soundWanted));$('#sound').setAttribute('aria-pressed',String(soundWanted));$('#sound').textContent=soundWanted?(soundRunning?'SOUND AN':'SOUND BEREIT'):'SOUND AUS';$('#sound').setAttribute('aria-label',soundWanted?'Sound ausschalten':'Sound einschalten');}
function toggleSound(){if(soundWanted&&!soundRunning){activateSound();return;}soundWanted=!soundWanted;try{sessionStorage.setItem('genug-sound',soundWanted?'on':'off');}catch{}if(soundWanted)activateSound();updateAudio();renderSound();}
function renderKeeps(){const focus=document.activeElement?.dataset.keep;$('#keeps').innerHTML=products.filter(p=>level(p)).map(p=>`<button class="keep" data-keep="${p.id}" aria-pressed="${selected.has(p.id)}">${selected.has(p.id)?'✓ ': '+ '}${currentName(p)}</button>`).join('');if(focus)$(`[data-keep="${focus}"]`)?.focus({preventScroll:true});}
