// Construction, infill and people: the board expands from 7×7 to 11×11 tiles.
function drawConstruction(x,y,age){const a=Math.max(0,1-age/2.5);for(let i=0;i<14;i++){const dx=((i*13)%31-15)*(1+age*.5),dy=-Math.sin(i)*age*7-age*7;rect(x+dx,y+dy,2,2,`rgba(207,205,133,${a*.7})`);}rect(x-22,y-8,2,11,'#d1b65e');rect(x+20,y-8,2,11,'#d1b65e');rect(x-22,y-8,44,2,'#8c8050');}
function citySites(){const size=landSize(),target=Math.min(500,3+Math.floor(state.upgrades*1.1));if(!Array.isArray(state.infill))state.infill=[];const key=size+':'+target;if(cityCache.key===key&&cityCache.ref===state.infill)return cityCache.sites;const occupied=new Set([...products.map(p=>p.a+':'+p.b),...state.infill.map(p=>p.a+':'+p.b)]);const candidates=[];for(let a=0;a<size;a++)for(let b=0;b<size;b++){if(a%8===3||b%8===4||occupied.has(a+':'+b)||(a===0&&b===0)||(a===size-1&&b===size-1))continue;candidates.push({a,b,rank:((a*37+b*19)%97)+(a+b<size?45:0)});}candidates.sort((a,b)=>a.rank-b.rank);for(const site of candidates){if(state.infill.length>=target)break;state.infill.push({a:site.a,b:site.b});}const sites=[...state.infill].sort((a,b)=>a.a+a.b-b.a-b.b);cityCache={key,ref:state.infill,sites};return sites;}
function drawDistricts(time,size){for(const {a,b} of citySites()){
const q=iso(a,b),screen=projectMap(q);if(screen.x<-50||screen.x>canvas.width+50||screen.y<-50||screen.y>canvas.height+90)continue;const height=9+((a*7+b*13)%18)+Math.min(18,state.upgrades*.35);if((a+b)%5===0&&state.upgrades>2){const swing=motionReduced?0:Math.sin(time*.0008+a)*8;rect(q.x-10,q.y-42,2,43,'#8f8851');rect(q.x-17,q.y-43,38,2,'#a99b58');rect(q.x+10+swing,q.y-40,1,14,'#7c8558');rect(q.x+7+swing,q.y-25,7,4,'#b8a967');block(q.x,q.y,12,11,height*.5,'#4b5940','#34442f','#6e7851');}else{block(q.x,q.y,11,12,height,'#4e5e47','#304b3b','#78815a');if(!motionReduced){const smokeY=((time*.007+a*11+b*3)%23);rect(q.x+2-smokeY*.18,q.y-height-12-smokeY,3,3,'#84917c35');}}}}
function drawLife(time,size){const p=pressure(),t=motionReduced?0:time;for(let n=0;n<2+Math.floor(state.upgrades*.6)&&n<22;n++){const travel=(t*.000012*(1+p)+n*.071)%1,q=n%2?iso(travel*(size-1),4):iso(3,travel*(size-1));const stride=motionReduced?0:Math.floor(t/180+n)%2;rect(q.x-1,q.y-5,2,2,n%3?'#a7b88b':'#c1af83');rect(q.x-2,q.y-3,3,4,n%2?'#8a794b':'#678e75');rect(q.x-2,q.y+1,1,2+stride,'#111d16');rect(q.x,q.y+1,1,3-stride,'#111d16');}
 if(state.upgrades>4){for(let n=0;n<Math.min(4,Math.floor(state.upgrades/5));n++){const q=iso(1+n*2,1),bob=motionReduced?0:Math.round(Math.sin(time*.001+n)*2);rect(q.x-8,q.y-42+bob,18,8,'#243c2f');rect(q.x-6+(Math.floor(t/350+n)%9),q.y-40+bob,3,3,'#c7d46d');}}
}
function drawCountryRoad(time){const start=iso(0,5),end={x:start.x-100,y:start.y+10};poly([[start.x,start.y-5],[end.x,end.y-5],[end.x-18,end.y+7],[start.x-2,start.y+7]],'#9d9d65');for(let i=0;i<7;i++){const x=start.x-i*15;rect(x,start.y+2,6,1,'#c6ce90');}const q=iso(0,5);rect(q.x-45,q.y-25,2,29,'#879565');rect(q.x-59,q.y-27,36,10,'#aebd77');ctx.font='7px monospace';ctx.fillStyle='#273d23';ctx.fillText('< LAND',q.x-56,q.y-20);}
function positionCountryRoad(){if($('#country-road').hidden)return;const q=projectMap(iso(0,5));$('#country-road').style.left=Math.max(14,Math.min($('#scene').clientWidth-155,(q.x-85*mapZoom())/canvas.width*$('#scene').clientWidth))+'px';$('#country-road').style.top=Math.max(65,Math.min($('#scene').clientHeight-90,(q.y+10)/canvas.height*$('#scene').clientHeight))+'px';}
