// The same pixel language opens into space, warm light and slower movement.
const countryCanvas=$('#country-canvas'),rctx=countryCanvas.getContext('2d',{alpha:false});
function rr(x,y,w,h,color){rctx.fillStyle=color;rctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function rp(points,color){rctx.fillStyle=color;rctx.beginPath();points.forEach((p,i)=>i?rctx.lineTo(Math.round(p[0]),Math.round(p[1])):rctx.moveTo(Math.round(p[0]),Math.round(p[1])));rctx.closePath();rctx.fill();}
function mix(a,b,t){const ah=parseInt(a.slice(1),16),bh=parseInt(b.slice(1),16);const out=[16,8,0].map(n=>Math.round(((ah>>n)&255)*(1-t)+((bh>>n)&255)*t));return `rgb(${out.join(',')})`;}
function drawCountry(){const w=countryCanvas.width,h=countryCanvas.height,progress=journey?.progress??1,t=motionReduced?0:countryTime;const dawn=Math.min(1,progress*1.65),horizon=Math.floor(h*.66);rr(0,0,w,h,mix('#0d1417','#d8ddbf',dawn));
 // Slow cloud banks, cut from rectangles rather than blurred shapes.
 for(let i=0;i<6;i++){const x=(i*97+Math.floor(t*.6))%(w+75)-45,y=30+(i*31)%Math.max(40,horizon-45);const c=mix('#1e2d2a','#e6e7cd',dawn);rr(x,y,40,5,c);rr(x+8,y-4,25,4,c);rr(x-7,y+5,57,3,c);}
 const sunY=h*.23;rr(w*.79,sunY,23,23,mix('#809066','#e6c985',dawn));rr(w*.79-3,sunY+4,29,15,mix('#809066','#e6c985',dawn));
 const ridge=[];for(let x=0;x<=w+20;x+=12)ridge.push([x,horizon-18-Math.sin(x*.017)*17-Math.cos(x*.032)*8]);rp([[0,horizon+20],...ridge,[w,horizon+20]],mix('#25362f','#a6b18c',dawn));
 const hills=[];for(let x=0;x<=w+20;x+=10)hills.push([x,horizon+8-Math.sin(x*.014+.9)*19]);rp([[0,horizon+50],...hills,[w,horizon+50]],mix('#2b4433','#819c68',dawn));rr(0,horizon+34,w,h,mix('#2e4532','#6d8d50',dawn));
 rp([[0,horizon+28],[w*.34,horizon+45],[w*.63,horizon+24],[w,horizon+38],[w,h*.83],[0,h*.9]],mix('#344a30','#829f5a',dawn));
 // A narrow stream with a few moving highlights.
 const river=[];for(let y=horizon+29;y<h+15;y+=7){const x=w*.73+Math.sin(y*.029)*w*.065;river.push([x,y]);}const rback=[...river].reverse().map(p=>[p[0]+8+(p[1]-horizon)*.07,p[1]]);rp([...river,...rback],mix('#35595a','#93b4a3',dawn));for(let n=0;n<11;n++){const y=horizon+38+((n*19+t*2)%(h-horizon-20)),x=w*.73+Math.sin(y*.029)*w*.065;rr(x+3,y,5,1,mix('#526f68','#c5d6b6',dawn));}
 // The road leaves the city behind and bends gently across the field.
 const roadY=h*.78;rp([[0,roadY-7],[w*.32,roadY-7],[w*.5,roadY-20],[w*.6,roadY-23],[w*.65,roadY-19],[w*.5,roadY-13],[w*.34,roadY+7],[0,roadY+12]],mix('#747a50','#c6bd8b',dawn));
 // Flowers and grass move only a pixel with the wind.
 for(let n=0;n<90;n++){const x=(n*61+19)%w,y=horizon+42+(n*37)%(Math.max(10,h-horizon-44));if(x>w*.69&&x<w*.87)continue;if(Math.abs(y-roadY)<13&&x<w*.61)continue;const sway=motionReduced?0:Math.round(Math.sin(t*.9+n)*.7);rr(x+sway,y,1,3,mix('#425d36','#567b3c',dawn));if(n%5===0)rr(x+sway-1,y-1,2,2,n%2?mix('#77694a','#d8c77d',dawn):mix('#6a6650','#ded8b1',dawn));}
 function rtree(x,y,size=1){const sway=motionReduced?0:Math.round(Math.sin(t*.7+x)*1);rr(x-1,y-14*size,3,16*size,mix('#3c4231','#6d6845',dawn));rr(x-13*size+sway,y-35*size,26*size,20*size,mix('#29442e','#4e7340',dawn));rr(x-9*size+sway,y-43*size,19*size,31*size,mix('#3a5835','#66864b',dawn));rr(x-17*size+sway,y-27*size,33*size,9*size,mix('#2d4730','#537a41',dawn));}
 rtree(w*.1,h*.74,.8);rtree(w*.91,h*.85,1.15);rtree(w*.94,h*.79,.8);rtree(w*.61,horizon+35,.6);
 // During the departure, the city slides off the left edge.
 if(progress<.7){const off=progress*w*1.9;for(let i=0;i<7;i++){const x=i*23-off,hh=35+(i*17)%40;rr(x,roadY-hh,21,hh,'#26392f');for(let j=8;j<hh;j+=10)rr(x+6,roadY-hh+j,3,3,'#889657');}}
 // The player walks, then sits down when the journey is over.
 const px=w*.34+Math.min(progress,.75)*w*.12,py=roadY-1;const walking=progress<1;const stride=walking&&!motionReduced?Math.floor(t*4)%2:0;rr(px-2,py-12,5,5,'#c1ae7b');rr(px-3,py-7,7,7,'#bd6a49');if(walking){rr(px-3,py,2,4+stride,'#344b35');rr(px+2,py,2,5-stride,'#344b35');}else{rr(px-4,py,10,2,'#344b35');rr(px+4,py-2,3,3,'#344b35');}
 // Small birds, moving slowly towards the open horizon.
 for(let i=0;i<3;i++){const x=(w*.2+t*2+i*23)%w,y=horizon-25-i*6;rr(x,y,2,1,mix('#2f4033','#6a7e61',dawn));rr(x-2,y-1,2,1,mix('#2f4033','#6a7e61',dawn));rr(x+2,y-1,2,1,mix('#2f4033','#6a7e61',dawn));}}
function resizeCountry(){const r=$('#retreat').getBoundingClientRect();countryCanvas.width=Math.max(160,Math.round(r.width/(r.width<700?2:3)));countryCanvas.height=Math.max(180,Math.round(r.height/(r.width<700?2:3)));drawCountry();}
new ResizeObserver(()=>{if(!$('#retreat').hidden)resizeCountry();}).observe($('#retreat'));
function beginCountry(immediate=false){window.FX?.enterOutro();if(!immediate&&state.finished)return;if(!state.pauseAt)state.pauseAt=Date.now();state.completed=true;try{sessionStorage.setItem('genug-done','1');}catch{}state.finished=true;state.escaped=true;failureOpen=false;document.body.classList.remove('system-failed','overloaded','very-overloaded','idle-world');document.body.classList.add('retreat-mode','finished');document.body.style.setProperty('--idle',0);document.body.style.setProperty('--pressure',0);clearTimeout(announcementTimer);$('#announcement').hidden=true;$('#floaters').replaceChildren();$('#build-menu').hidden=true;$('#experience').hidden=true;$('#ending').hidden=true;$('#retreat').hidden=false;$('#outro').hidden=true;$('#return-outro').hidden=true;$('#skip-journey').hidden=false;$('#journey-label').textContent=immediate?'DEIN WEG. DEINE ZEIT.':state.goal?.reached?'DU DARFST DEINEN ERFOLG GENIESSEN.':'ZEIT FÜR DICH GEHÖRT ZU DEINEM WEG.';journey={progress:immediate?1:0,elapsed:0,duration:motionReduced?1.2:13.5};countryTime=0;if(!immediate)selected=new Set(products.filter(p=>level(p)).slice(0,3).map(p=>p.id));resizeCountry();updateAudio();persist();window.scrollTo({top:0,behavior:'instant'});if(immediate)arriveCountry();else $('#skip-journey').focus({preventScroll:true});}
function advanceCountry(dt){countryTime+=dt;if(journey&&journey.progress<1){journey.elapsed+=dt;journey.progress=Math.min(1,journey.elapsed/journey.duration);if(journey.progress>=1)arriveCountry();}if(!motionReduced||countryTime-lastCountryFrame>.25){drawCountry();lastCountryFrame=countryTime;}}
function arriveCountry(){if(!journey)journey={progress:1,elapsed:0,duration:1};journey.progress=1;$('#journey-label').textContent='DU BIST ANGEKOMMEN.';$('#skip-journey').hidden=true;$('#outro').hidden=false;$('#outro').classList.add('arrived');window.FX?.arrive();drawCountry();$('#outro h1').tabIndex=-1;$('#outro h1').focus({preventScroll:true});}
function scheduleCountryAudio(){if(!audio||!soundWanted||!soundRunning||document.hidden||audio.state!=='running'){if(audio)ambientNext=audio.currentTime+.1;return;}const t=audio.currentTime;if(ambientNext<t)ambientNext=t+.1;if(ambientNext<t+.15){for(const [i,f] of [196,293.66,392].entries()){const osc=audio.createOscillator(),g=audio.createGain();osc.type='sine';osc.frequency.value=f;g.gain.setValueAtTime(0,ambientNext+i*.22);g.gain.linearRampToValueAtTime(.05,ambientNext+1.8+i*.22);g.gain.exponentialRampToValueAtTime(.0001,ambientNext+5);osc.connect(g).connect(ambientBus);osc.start(ambientNext+i*.22);osc.stop(ambientNext+5.1);}ambientNext+=7;}}
$('#country-road').addEventListener('click',()=>beginCountry());$('#skip-journey').addEventListener('click',arriveCountry);$('#retreat-sound').addEventListener('click',toggleSound);$('#view-round').addEventListener('click',()=>{document.body.classList.remove('retreat-mode');showEnding();});$('#back-country').addEventListener('click',()=>beginCountry(true));$('#stay-country').addEventListener('click',()=>{$('#outro').hidden=true;$('#return-outro').hidden=false;$('#return-outro').focus({preventScroll:true});});$('#return-outro').addEventListener('click',()=>{$('#return-outro').hidden=true;$('#outro').hidden=false;$('#stay-country').focus({preventScroll:true});});

