function renderPersonalGoal(){const g=state.goal;if(!g||!products.some(p=>p.id===g.id)){state.goal={id:'house',level:15,reached:false};}if(!state.goal.reached&&state.goal.level<5)state.goal.level=5;const goal=state.goal,p=products.find(p=>p.id===goal.id),target=p.tiers[Math.min(goal.level-1,p.tiers.length-1)]+(goal.level>p.tiers.length?' / STUFE '+goal.level:'');$('#personal-goal-title').textContent=goal.reached?'ERREICHT: '+target:target;$('#personal-goal-progress').style.width=Math.min(100,level(p)/goal.level*100)+'%';$('#routine-label').textContent=(state.rest?'ROUTINE + ERHOLUNG':'ROUTINE')+' / +'+Math.round((routineBonus()-1)*100)+' % ERTRAG';}
function checkPersonalGoal(){const g=state.goal,p=products.find(p=>p.id===g.id);if(g.reached||level(p)<g.level)return;g.reached=true;renderPersonalGoal();state.achievements=state.achievements||[];state.achievements.push({id:p.id,level:g.level,time:state.seconds});addFeed('HAUPTZIEL ERREICHT.',`«${currentName(p)}» steht. Nimm dir Zeit, es zu spüren. Du darfst weitermachen, wenn du magst.`,'DEIN ZIEL','milestone');notify('HAUPTZIEL ERREICHT. NIMM DIR ZEIT.');persist();}
